#include "atomic_replace.hpp"
// Exact link reconstruction, with explicitly bounded local searches.
// Fix (t-1) coordinates T. Every codeword containing T becomes T union R.
// Their remainders R must be disjoint: the refill is uniform-set matching,
// constrained by all critical shadows owned by the untouched boundary.
// The candidate universe is exhaustively generated by a leave-graph clique
// search. A bounded maximum-clique kernel selects disjoint remainders.
// Neutral changes are valid equal-cardinality matchings, not near-codes.
#include <algorithm>
#include <array>
#include <bit>
#include <chrono>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <functional>
#include <iostream>
#include <numeric>
#include <random>
#include <regex>
#include <stdexcept>
#include <string>
#include <unordered_set>
#include <vector>
using namespace std; using Word=uint64_t;using Clock=chrono::steady_clock;
vector<int> points(Word x){vector<int>p;while(x){p.push_back(countr_zero(x));x&=x-1;}return p;}
vector<Word> subsets(Word mask,int k){vector<int>p=points(mask);vector<Word>out;function<void(int,int,Word)>go=[&](int s,int left,Word x){if(!left){out.push_back(x);return;}for(int i=s;i<=int(p.size())-left;i++)go(i+1,left-1,x|(Word(1)<<p[i]));};go(0,k,0);return out;}
int main(int argc,char**argv){try{
 if(argc<9||argc>10)throw runtime_error("Usage: link_reconstruct INPUT N D W SEED SECONDS OUTPUT NEUTRAL_PROB [MAX_NODES]");
 int n=stoi(argv[2]),d=stoi(argv[3]),w=stoi(argv[4]),t=w-(d+1)/2+1,r=w-t+1;uint64_t seed=stoull(argv[5]);double seconds=stod(argv[6]),neutral=stod(argv[8]);int node_limit=argc==10?stoi(argv[9]):20000;
 if(n>64||n<1||t<2||t>4||w>12||w>n||r<1||neutral<0||neutral>1||seconds<=0||node_limit<1)throw runtime_error("Unsupported parameters: require n<=64, 2<=t<=4");
 vector<Word>C;ifstream f(argv[1]);if(!f)throw runtime_error("Cannot read input");string line;regex num("[0-9]+");
 while(getline(f,line)){if(line.empty()||line[0]=='#')continue;Word x=0;int k=0;for(sregex_iterator it(line.begin(),line.end(),num),end;it!=end;++it){int a=stoi(it->str())-1;if(a<0||a>=n||((x>>a)&1))throw runtime_error("Invalid coordinate");x|=Word(1)<<a;k++;}if(!k)continue;if(k!=w)throw runtime_error("Invalid row weight");C.push_back(x);}
 array<array<uint64_t,5>,65> choose{};for(int a=0;a<=n;a++){choose[a][0]=1;for(int b=1;b<=4;b++)choose[a][b]=a?choose[a-1][b]+choose[a-1][b-1]:0;}
 auto rank=[&](Word x){uint64_t z=0;int k=1;while(x){int a=countr_zero(x);x&=x-1;z+=choose[a][k++];}return z;};
 vector<Word>owner(choose[n][t]);
 auto place=[&](Word x){auto ss=subsets(x,t);for(Word T:ss)if(owner[rank(T)])throw runtime_error("Repeated critical subset in code");for(Word T:ss)owner[rank(T)]=x;};
 for(Word x:C)place(x);const int before=C.size();
 Word full=n==64?~Word(0):(Word(1)<<n)-1;vector<Word>links=subsets(full,t-1);mt19937_64 rng(seed);shuffle(links.begin(),links.end(),rng);
 auto start=Clock::now();auto elapsed=[&](){return chrono::duration<double>(Clock::now()-start).count();};
 uint64_t linkscanned=0,nonnull=0,enum_nodes=0,match_nodes=0,exact=0,incomplete=0,neutrals=0,gains=0,round=0;size_t maxpool=0;
 ofstream trace(string(argv[7])+".trades.jsonl");
 auto save=[&](){string temp=string(argv[7])+".tmp";ofstream out(temp);out<<"# Link reconstruction; one-based supports; independently verify.\n";auto cc=C;sort(cc.begin(),cc.end());for(Word x:cc){auto p=points(x);for(int j=0;j<w;j++)out<<(j?" ":"")<<p[j]+1;out<<'\n';}out.close();replace_checkpoint(temp,argv[7]);};save();
 for(;elapsed()<seconds;round++){
  if(round)shuffle(links.begin(),links.end(),rng);
  for(Word T:links){if(elapsed()>=seconds)break;linkscanned++;
   vector<Word>old;for(Word x:C)if((x&T)==T)old.push_back(x);
   if(old.empty())continue;nonnull++;
   for(Word x:old)for(Word s:subsets(x,t))owner[rank(s)]=0;
   vector<Word>fixed_subsets=subsets(T,t-2);array<Word,64>adj{};Word remaining=full&~T;
   for(Word ii=remaining;ii;ii&=ii-1){int a=countr_zero(ii);for(Word jj=remaining & (a==63?Word(0):(~Word(0)<<(a+1)));jj;jj&=jj-1){int b=countr_zero(jj);Word pair=(Word(1)<<a)|(Word(1)<<b);bool ok=true;for(Word u:fixed_subsets)if(owner[rank(pair|u)]){ok=false;break;}if(ok){adj[a]|=Word(1)<<b;adj[b]|=Word(1)<<a;}}}
   vector<Word>pool;bool enum_complete=true;uint64_t local_enum=0;
   function<void(Word,Word,int)>enumerate=[&](Word chosen,Word available,int depth){if(!enum_complete)return;if((++local_enum&1023)==0 && elapsed()>seconds){enum_complete=false;return;}if(pool.size()>=5000){enum_complete=false;return;}
    if(depth==r){pool.push_back(chosen);return;}if(popcount(available)<r-depth)return;
    while(available){int x=countr_zero(available);Word bit=Word(1)<<x;available&=available-1;if(popcount(available)+1<r-depth)return;bool ok=true;
      if(depth>=2){for(Word ss:subsets(T|chosen,t-1))if(owner[rank(ss|bit)]){ok=false;break;}}
      if(ok)enumerate(chosen|bit,available&adj[x],depth+1);
      if(!enum_complete)return;
    }
   };enumerate(0,remaining,0);enum_nodes+=local_enum;maxpool=max(maxpool,pool.size());
   if(!enum_complete){for(Word x:old)place(x);incomplete++;continue;}
   // All previous remainders must occur in the exhaustive pool.
   unordered_set<Word>universe(pool.begin(),pool.end());for(Word x:old)if(!universe.count(x&~T))throw runtime_error("Enumeration omitted an incumbent");
   shuffle(pool.begin(),pool.end(),rng);vector<int>best;for(int i=0;i<int(pool.size());i++)if(find(old.begin(),old.end(),pool[i]|T)!=old.end())best.push_back(i);
   vector<int>greedy;Word used=0;for(int i=0;i<int(pool.size());i++)if(!(used&pool[i])){used|=pool[i];greedy.push_back(i);}if(greedy.size()>best.size()||(greedy.size()==best.size()&&double(rng()%1000000)/1000000<neutral))best=greedy;
   vector<int>initial(pool.size());iota(initial.begin(),initial.end(),0);vector<int>selected;uint64_t nodes=0;bool solved=true;
   function<void(const vector<int>&)>expand=[&](const vector<int>&P){if(!solved)return;if(++nodes>uint64_t(node_limit)||(nodes%256==0&&elapsed()>seconds)){solved=false;return;}
     Word all=0;for(int i:P)all|=pool[i];if(selected.size()+min(P.size(),size_t(popcount(all)/r))<=best.size())return;
     // Greedy coloring of the compatibility graph gives a clique upper bound.
     vector<int>remaining=P,order,bound;int color=0;
     while(!remaining.empty()){color++;vector<int>Q=remaining;while(!Q.empty()){int v=Q.back();Q.pop_back();order.push_back(v);bound.push_back(color);remaining.erase(find(remaining.begin(),remaining.end(),v));Q.erase(remove_if(Q.begin(),Q.end(),[&](int u){return !(pool[u]&pool[v]);}),Q.end());}}
     for(int k=int(order.size())-1;k>=0;k--){if(selected.size()+bound[k]<=best.size())return;int v=order[k];selected.push_back(v);vector<int>next;for(int j=0;j<k;j++)if(!(pool[v]&pool[order[j]]))next.push_back(order[j]);
       if(next.empty()){if(selected.size()>best.size())best=selected;}else expand(next);selected.pop_back();if(!solved)return;
     }
   };expand(initial);match_nodes+=nodes;if(solved)exact++;else incomplete++;
   vector<Word>replacement;for(int i:best)replacement.push_back(pool[i]|T);
   if(replacement.size()<old.size())throw runtime_error("Refill lost incumbent");
   auto aa=replacement,bb=old;sort(aa.begin(),aa.end());sort(bb.begin(),bb.end());bool changed=aa!=bb;
   if(changed){C.erase(remove_if(C.begin(),C.end(),[&](Word x){return (x&T)==T;}),C.end());C.insert(C.end(),replacement.begin(),replacement.end());
    trace<<"{\"link_hex\":\""<<hex<<T<<"\",\"removed_hex\":[";for(int i=0;i<int(old.size());i++)trace<<(i?",":"")<<'"'<<old[i]<<'"';trace<<"],\"inserted_hex\":[";for(int i=0;i<int(replacement.size());i++)trace<<(i?",":"")<<'"'<<replacement[i]<<'"';trace<<"],\"pool\":"<<dec<<pool.size()<<",\"optimal\":"<<(solved?"true":"false")<<"}\n";
    if(replacement.size()>old.size()){gains+=replacement.size()-old.size();save();cout<<"{\"event\":\"gain\",\"links_scanned\":"<<linkscanned<<",\"removed\":"<<old.size()<<",\"inserted\":"<<replacement.size()<<",\"size\":"<<C.size()<<",\"pool\":"<<pool.size()<<",\"optimal\":"<<(solved?"true":"false")<<",\"seconds\":"<<elapsed()<<"}"<<endl;}else neutrals++;
   }
   for(Word x:replacement)place(x);
  }
 }
 save();cout<<"{\"event\":\"done\",\"seed\":"<<seed<<",\"n\":"<<n<<",\"d\":"<<d<<",\"w\":"<<w<<",\"parent\":"<<before<<",\"size\":"<<C.size()<<",\"links_scanned\":"<<linkscanned<<",\"nonnull_links\":"<<nonnull<<",\"solved_link_instances\":"<<exact<<",\"incomplete_instances\":"<<incomplete<<",\"neutrals\":"<<neutrals<<",\"max_pool\":"<<maxpool<<",\"enum_nodes\":"<<enum_nodes<<",\"match_nodes\":"<<match_nodes<<",\"seconds\":"<<elapsed()<<"}"<<endl;
}catch(const exception&e){cerr<<e.what()<<'\n';return 2;}}
